(function(root){
const M=typeof module!=='undefined'?require('./model.js'):root.ReconModel;
function money(value){if(typeof value==='number'){if(!Number.isFinite(value))throw Error('金额不是有效数字');value=String(value);}let s=String(value??'').trim().normalize('NFKC');if(!s)throw Error('金额为空');let negative=false;if(/^\(.*\)$/.test(s)){negative=true;s=s.slice(1,-1);}s=s.replace(/^(?:CNY|RMB|USD|EUR|GBP|HKD|人民币|[¥￥$€£])\s*/i,'').trim();if(s.includes(',')){if(!/^[+-]?\d{1,3}(,\d{3})+(\.\d{1,2})?$/.test(s))throw Error('金额千分位格式无效');s=s.replaceAll(',','');}if(!/^[+-]?\d+(\.\d{1,2})?$/.test(s))throw Error('金额须为最多两位小数，不支持公式或科学计数法');const sign=s.startsWith('-')?-1:1;if(negative&&sign<0)throw Error('金额符号冲突');s=s.replace(/^[+-]/,'');const [whole,frac='']=s.split('.');const cents=Number(whole)*100+Number(frac.padEnd(2,'0'));if(!Number.isSafeInteger(cents))throw Error('金额超过安全范围');return cents*(negative?-1:sign);}
function day(value,date1904=false){if(typeof value==='number'){if(!Number.isInteger(value)||value<1||value>200000||(!date1904&&value===60))throw Error('Excel 日期序号无效');return (date1904?Date.UTC(1904,0,1):Date.UTC(1899,11,30))/86400000+value+(date1904||value>=60?0:1);}const s=String(value??'').trim(),m=/^(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})日?$/.exec(s);if(!m)throw Error('日期须为 YYYY-MM-DD 或 Excel 日期单元格');const y=+m[1],mo=+m[2],d=+m[3],t=Date.UTC(y,mo-1,d),dt=new Date(t);if(y<1900||y>2200||dt.getUTCFullYear()!==y||dt.getUTCMonth()!==mo-1||dt.getUTCDate()!==d)throw Error('日期不存在或超出范围');return t/86400000;}
const dateString=n=>new Date(n*86400000).toISOString().slice(0,10);
function normalize(rows,map,side,options={}){const valid=[],errors=[];rows.forEach((r,i)=>{try{if(r.every(v=>v===null||v===undefined||String(v).trim()===''))return;let amount;if(map.mode==='split'){const inc=r[map.income],out=r[map.expense],a=inc===null||inc===undefined||String(inc).trim()===''?0:money(inc),b=out===null||out===undefined||String(out).trim()===''?0:money(out);if(a<0||b<0||a&&b)throw Error('收入支出列必须非负，且同一行不能同时有收入和支出');amount=a-b;}else amount=money(r[map.amount]);if(map.reverse)amount=-amount;if(!amount)throw Error('零金额记录不参与对账');const date=day(r[map.date],options.date1904);const currency=String(map.currency>=0?(r[map.currency]??''):map.defaultCurrency||'CNY').trim().toUpperCase();if(!/^(CNY|USD|EUR|GBP|HKD)$/.test(currency))throw Error('币种为空或不支持（支持 CNY/USD/EUR/GBP/HKD）');const description=String(r[map.description]??'').trim();if(!description)throw Error('摘要为空');const ref=map.reference>=0?String(r[map.reference]??'').trim():'';const sourceRow=i+(options.headerRow||1)+1;valid.push({id:side+':'+sourceRow,side,sourceRow,date,dateText:dateString(date),amount,currency,description,ref});}catch(e){errors.push({side,sourceRow:i+(options.headerRow||1)+1,message:e.message,raw:r});}});return {valid,errors};}
function duplicates(rows){const groups=new Map(),refs=new Map();rows.forEach(r=>{const key=[r.date,r.amount,r.currency,M.clean(r.description)].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r.id);if(r.ref){const rk=r.currency+'|'+r.ref.toUpperCase();if(!refs.has(rk))refs.set(rk,[]);refs.get(rk).push(r.id);}});return new Set([...groups.values(),...refs.values()].filter(g=>g.length>1).flat());}
function reconcile(ledger,bank,model,options={}){const maxDays=options.maxDays??3,diffCents=options.diffCents??10000;if(!Number.isInteger(maxDays)||maxDays<0||maxDays>31||!Number.isSafeInteger(diffCents)||diffCents<0)throw Error('匹配设置无效');const dl=duplicates(ledger),db=duplicates(bank),matches=[],usedL=new Set(),usedB=new Set();const refEqual=(a,b)=>a.ref&&b.ref&&a.ref.toUpperCase()===b.ref.toUpperCase();const refConflict=(a,b)=>a.ref&&b.ref&&!refEqual(a,b);
const exact=(a,b)=>a.currency===b.currency&&a.amount===b.amount&&Math.abs(a.date-b.date)<=maxDays&&!dl.has(a.id)&&!db.has(b.id)&&!refConflict(a,b)&&(refEqual(a,b)||(a.date===b.date&&M.clean(a.description)===M.clean(b.description)));
const le=new Map(ledger.map(a=>[a.id,bank.filter(b=>exact(a,b))])),be=new Map(bank.map(b=>[b.id,ledger.filter(a=>exact(a,b))]));ledger.forEach(a=>{const choices=le.get(a.id);if(choices.length===1&&be.get(choices[0].id).length===1){const b=choices[0];usedL.add(a.id);usedB.add(b.id);matches.push({ledgerId:a.id,bankId:b.id,kind:'auto',reason:refEqual(a,b)?'金额、币种及唯一编号一致，日期在窗口内':'金额、币种、日期和规范化摘要一致，双方候选唯一',diff:0});}});
const candidates=[];ledger.filter(a=>!usedL.has(a.id)).forEach(a=>{const arr=[];bank.filter(b=>!usedB.has(b.id)).forEach(b=>{const days=Math.abs(a.date-b.date),diff=b.amount-a.amount;if(a.currency!==b.currency||Math.sign(a.amount)!==Math.sign(b.amount)||days>maxDays||Math.abs(diff)>diffCents)return;const textScore=model.score(a.description,b.description),sameRef=refEqual(a,b),conflict=!!refConflict(a,b);if(textScore<0.3&&!sameRef)return;const score=Math.max(0,0.8*textScore+0.15*(1-days/(maxDays+1))+0.05*(diff===0?1:0)-(conflict?0.15:0));const reasons=[diff===0?'金额一致':'金额差异 '+(diff/100).toFixed(2)+' '+a.currency,'相差 '+days+' 天','文本模型分数 '+textScore.toFixed(2)];if(sameRef)reasons.push('编号一致');if(conflict)reasons.push('编号冲突，请核查');if(dl.has(a.id)||db.has(b.id))reasons.push('疑似重复，不能自动确认');arr.push({ledgerId:a.id,bankId:b.id,score,textScore,days,diff,reasons,conflict});});arr.sort((a,b)=>b.score-a.score||a.days-b.days||a.bankId.localeCompare(b.bankId));arr.slice(0,3).forEach(c=>candidates.push(c));});return {matches,candidates,duplicateLedger:[...dl],duplicateBank:[...db],options:{maxDays,diffCents}};}
function confirm(matches,candidate){if(matches.some(m=>m.ledgerId===candidate.ledgerId||m.bankId===candidate.bankId))throw Error('该记录已被其他匹配使用，请先撤销');return [...matches,{ledgerId:candidate.ledgerId,bankId:candidate.bankId,kind:'manual',reason:candidate.reasons.join('；'),diff:candidate.diff}];}
function totals(rows){const out={};rows.forEach(r=>{out[r.currency]=(out[r.currency]||0)+r.amount;if(!Number.isSafeInteger(out[r.currency]))throw Error('汇总金额超过安全范围');});return out;}
function csvCell(v){let s=String(v??'');if(/^[\s\u0000-\u001f]*[=+@-]/.test(s)&&!/^[-+]\d+(\.\d+)?$/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportRows(ledger,bank,result){const usedL=new Set(result.matches.map(m=>m.ledgerId)),usedB=new Set(result.matches.map(m=>m.bankId));const rows=[['状态','账本源行','流水源行','币种','账本日期','流水日期','账本金额','流水金额','差额(流水减账本)','账本摘要','流水摘要','账本编号','流水编号','匹配依据']];const lmap=new Map(ledger.map(r=>[r.id,r])),bmap=new Map(bank.map(r=>[r.id,r]));result.matches.forEach(m=>{const a=lmap.get(m.ledgerId),b=bmap.get(m.bankId);rows.push([m.kind==='auto'?'自动匹配':'人工确认',a.sourceRow,b.sourceRow,a.currency,a.dateText,b.dateText,(a.amount/100).toFixed(2),(b.amount/100).toFixed(2),((b.amount-a.amount)/100).toFixed(2),a.description,b.description,a.ref,b.ref,m.reason]);});ledger.filter(r=>!usedL.has(r.id)).forEach(a=>rows.push(['账本未匹配',a.sourceRow,'',a.currency,a.dateText,'',(a.amount/100).toFixed(2),'','',a.description,'',a.ref,'','']));bank.filter(r=>!usedB.has(r.id)).forEach(b=>rows.push(['流水未匹配','',b.sourceRow,b.currency,'',b.dateText,'',(b.amount/100).toFixed(2),'','',b.description,'',b.ref,'']));return rows;}
const api={money,day,dateString,normalize,duplicates,reconcile,confirm,totals,csvCell,exportRows};root.ReconEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
